    var ADDS = [{"p":"PART 1. 광복과 대한민국 정부 수립","q":[{"answer":"O","text":"제헌 국회가 제정한 제헌 헌법은 대한민국이 민주 공화국임을 규정하였으며, 제헌 국회의원의 임기를 2년으로 정하였다.","exp":"제헌 헌법은 국호를 대한민국으로 하고 대한민국이 민주 공화국임과 주권이 국민에게 있음을 밝혔으며, 제헌 국회의원의 임기는 2년으로 규정하였다. 황제의 전제 정치를 규정한 대한 제국의 대한국 국제와는 성격이 정반대이다.","src":"한능검 제75회"},{"answer":"X","text":"제헌 국회가 제정한 제헌 헌법은 황제가 육해군 통수권을 장악하는 전제 정치 체제임을 규정하였으며, 제헌 국회의원의 임기를 2년으로 정하였다.","exp":"앞부분이 틀렸다. 황제의 전제 정치와 군 통수권을 규정한 것은 대한 제국이 반포한 대한국 국제이다. 제헌 헌법은 대한민국이 민주 공화국임을 규정하였다."}],"tb":[],"wi":[]},{"p":"PART 2. 6·25 전쟁과 이승만 정부·4·19 혁명","q":[{"answer":"O","text":"6·25 전쟁 중 부산에서 발췌 개헌을 강행한 이승만 정부 때, 정전 협정 체결을 전후하여 한미 상호 방위 조약이 체결되어 미군 주둔의 근거가 마련되었다.","exp":"한미 상호 방위 조약은 정전 협정이 체결된 1953년 이승만 정부 때 맺어져 이후 주한 미군 주둔의 법적 근거가 되었다. 전쟁 중 부산에서의 발췌 개헌 역시 이승만 정부 시기의 일이다.","src":"한능검 제75회"},{"answer":"X","text":"6·25 전쟁 중 부산에서 발췌 개헌을 강행한 이승만 정부 때, 서울과 부산을 잇는 경부 고속 도로가 개통되어 전국이 일일생활권으로 묶였다.","exp":"정부와 시기가 틀렸다. 경부 고속 도로 개통은 박정희 정부 때의 일이다. 이승만 정부 때 체결된 것은 한미 상호 방위 조약이다."}],"tb":[],"wi":[]},{"p":"PART 3. 박정희 정부·유신·5·18·6월 민주 항쟁","q":[{"answer":"O","text":"동일방직·YH 무역 사건 등 여성 노동자들의 생존권 투쟁이 이어지던 박정희 정부 유신 체제기에, 긴급 조치 철폐 등을 요구하는 3·1 민주 구국 선언이 발표되었다.","exp":"3·1 민주 구국 선언은 1976년 유신 체제하에서 재야인사·종교계가 긴급 조치 철폐와 유신 헌법 폐지 등을 요구하며 발표한 선언이다. 유신 말기의 동일방직·YH 무역 등 노동 운동과 같은 시기의 저항 흐름으로 묶어 이해한다.","src":"한능검 제75회"},{"answer":"X","text":"부천 경찰서 성 고문 사건으로 정권의 인권 탄압이 드러난 전두환 정부 시기에, 긴급 조치 철폐 등을 요구하는 3·1 민주 구국 선언이 발표되었다.","exp":"시기와 정부가 틀렸다. 3·1 민주 구국 선언은 1976년 박정희 정부 유신 체제기에 발표되었다. 부천 경찰서 성 고문 사건은 전두환 정부 시기의 일로 서로 다른 시기의 사실을 뒤섞은 함정이다."}],"tb":[{"k":"p","t":"3·1 민주 구국 선언(1976): 유신 체제하에서 재야인사·종교계가 명동 성당에 모여 긴급 조치 철폐, 유신 헌법 폐지, 박정희 정권 퇴진 등을 요구하며 발표한 민주화 선언이다."}],"wi":[]},{"p":"PART 4. 민주주의 발전·경제 성장·통일 정책","q":[{"answer":"O","text":"문민정부를 표방하며 하나회를 청산하고 금융 실명제를 실시한 김영삼 정부 때, 거창 사건 등 관련자의 명예 회복에 관한 특별 조치법이 제정되었다.","exp":"거창 사건 등 관련자의 명예 회복에 관한 특별 조치법은 1996년 김영삼 정부 때 제정되어 6·25 전쟁 중 민간인 희생 사건 관련자의 명예 회복 근거가 되었다. 하나회 청산·금융 실명제·역사 바로 세우기 등도 같은 정부의 일이다.","src":"한능검 제75회"},{"answer":"X","text":"서울 올림픽을 개최하고 소련·중국과 국교를 맺은 노태우 정부 때, 거창 사건 등 관련자의 명예 회복에 관한 특별 조치법이 제정되었다.","exp":"정부가 틀렸다. 거창 사건 관련자 명예 회복 특별 조치법은 김영삼 정부 때 제정되었다. 서울 올림픽 개최와 북방 외교는 노태우 정부의 일로 서로 다른 정부의 업적을 뒤섞은 함정이다."}],"tb":[{"k":"p","t":"거창 사건 등 관련자 명예 회복 특별 조치법(1996): 김영삼 정부가 6·25 전쟁 중 거창 등지에서 벌어진 민간인 희생 사건 관련자의 명예를 회복하기 위해 제정한 법으로, '역사 바로 세우기'의 연장선에 있다."}],"wi":[]}];
    for (var ai = 0; ai < ADDS.length; ai++) { insQ(ADDS[ai].p, ADDS[ai].q); insT(ADDS[ai].p, ADDS[ai].tb, ADDS[ai].wi); }
